css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; }
.dcx a{ color: #0FA487; text-decoration: none; }
.dcx a:hover{ color: #0B8A71; }
.dcx :focus-visible{ outline: 2px solid #3FE0BB; outline-offset: 3px; }
.dcx select{ font: inherit; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-herogrid],.dcx [data-split],.dcx [data-conv],.dcx [data-cta],.dcx [data-foot]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 44px !important; }
.dcx [data-h2]{ font-size: 34px !important; }
.dcx [data-spacer]{ display: none !important; }
.dcx [data-slotbg]{ opacity: .35; }
}
@media (max-width: 640px){.dcx [data-cards],.dcx [data-heroicons]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 36px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
}
